# Chacha decryption
rol32 = lambda v, c: ((v << c) & 0xFFFFFFFF) | (v >> (32 - c))

def quarter_round(x, a, b, c, d):
    x[a] = (x[a] + x[b]) & 0xFFFFFFFF; x[d] ^= x[a]; x[d] = rol32(x[d], 16)
    x[c] = (x[c] + x[d]) & 0xFFFFFFFF; x[b] ^= x[c]; x[b] = rol32(x[b], 12)
    x[a] = (x[a] + x[b]) & 0xFFFFFFFF; x[d] ^= x[a]; x[d] = rol32(x[d], 8)
    x[c] = (x[c] + x[d]) & 0xFFFFFFFF; x[b] ^= x[c]; x[b] = rol32(x[b], 7)

def chacha_block(consts, key, nonce, cnt):
    """Generates a single 64-byte keystream block using ChaCha algorithm."""
    ctx = consts + list(key) + [cnt, 0] + nonce
    state = list(ctx)

    for i in range(10):
        # Odd round (columns)
        quarter_round(state, 0, 4, 8,  12)
        quarter_round(state, 1, 5, 9,  13)
        quarter_round(state, 2, 6, 10, 14)
        quarter_round(state, 3, 7, 11, 15)
        # Even round (diagonals)
        quarter_round(state, 0, 5, 10, 15)
        quarter_round(state, 1, 6, 11, 12)
        quarter_round(state, 2, 7, 8,  13)
        quarter_round(state, 3, 4, 9,  14)

    new_state = [(state[i] + ctx[i]) & 0xFFFFFFFF for i in range(16)]
    return struct.pack('<16L', *new_state)


# ----------------------------------------------------------------------------------------
def decrypt_func_chacha(encr, key_bytes, start_idx):
    """Decrypts a blob of code using (a custom) Chacha."""
    # Constants from u_init_chacha20_custom_consts() at 401E67h
    consts = [0xB979379E, 0x157C4A7F, 0x60C09CF3, 0x34C8ED5C]    
    # Nonce from u_decrypt_code() at 404059h
    nonce = [0x0D0C0B0A, 0x11100F0E] 
    # Key as 8 DWORDs
    key = struct.unpack('<8I', key_bytes)
    
    cnt = start_idx // 64
    keystream = chacha_block(consts, key, nonce, cnt)
    decr = []
    for i in range(len(encr)):    
        if (start_idx + i) % 64 == 0:
            # We used all the keystream. Generate the next one.
            cnt = (start_idx + i) // 64
            keystream = chacha_block(consts, key, nonce, cnt)

        decr_byte = encr[i] ^ keystream[(start_idx+i) % 64]
        decr.append(decr_byte)
        print(f'[+]    Decrypted: .pc:{0x40A000 + start_idx + i:X} ~> {decr_byte:02X}')
        
    return decr


