    #
    # To do this we have to substitute the 0xCC opcodes with the correct
    # jcc instruction from JCC_COND. The condition is taken from JCC_MAP.
    #
    # However, there is a problem: Not all `int 3` instructions need to be
    # substituted. Consider this for example:
    #
    #   .pc:00010:    CC ~> jmp 0x17
    #   ... 
    #   .pc:00016:    CC ~> should be ignored
    #   .pc:00017:    xx
    #
    # Here, we substitute the first CC instruction with a jmp to the
    # address 0x17. However, in address 0x16 we have another CC instruction
    # which is never be executed (or substituted). If we substitute it, we
    # will destroy the byte xx at address 0x17.
    #
    # At this point I was too tired to think of a good heuristic, so I did
    # this job manually. The program just does all candidate jump
    # substitutions and then I decided manually which ones to revert.
    # --------------------------------------------------------------------
    print(f'[+] Fixing `int 3` instructions ...')

    fixed_func_bytes = []
    skip = 0
    cnt = 0
    for i, b in enumerate(func_bytes):
        if i < skip:
            print(f'[+] .pc:{0x40A000 + i:X} ~> {b:02X} (SKIP)')
            continue
        else:
            print(f'[+] .pc:{0x40A000 + i:X} ~> {b:02X}')

        if b == 0xcc:  # int 3 ?
            base, cond, off, sz = JCC_MAP[i]
            mnem, op1, op2 = JCC_COND[cond]
            print(f'[+] Found `int 3`. Substitute with: `{mnem} 0x{off:02X}` ({sz} bytes)')
        
            # The 0xCC and the next sz-1 bytes need to be substituted.
            if sz == 2:
                new_insn = [op1[0], off]
            else:
                new_insn = [op2[0]] + list(struct.pack('<L', off))            

            fixed_func_bytes += new_insn
            print('[+] New insn bytes: ' + ' '.join(f'{x:02X}' for x in new_insn))
            
            skip = i + sz  # We need to skip the next sz bytes.
            cnt += 1
        else:
            fixed_func_bytes.append(b)


    print(f'[+] Done. Total jumps found: {cnt}')
    print( '[+] Program finished successfully.')
